// Builds supabase/functions/_shared/streaks.ts: a single self-contained copy of the streak logic
// for the Deno Edge Functions (they cannot import from lib/). The app's lib/ stays the source of
// truth; a unit test (lib/edge-sync.test.ts) fails if the generated file drifts.
//
//   npm run sync:edge
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const OUT = path.join(root, "supabase/functions/_shared/streaks.ts");

const SOURCES = [
  "lib/timezone.ts",
  "lib/streaks/schedule.ts",
  "lib/streaks/daily.ts",
  "lib/streaks/weekly.ts",
  "lib/streaks/broken.ts",
  "lib/streaks/milestones.ts",
];

const HEADER = `// AUTO-GENERATED by scripts/sync-edge-streaks.mjs. DO NOT EDIT.
// Source of truth: lib/timezone.ts + lib/streaks/*. Regenerate with \`npm run sync:edge\`.

// Minimal row shape the Edge Functions read from public.habits.
export type Habit = {
  id: string;
  frequency_type: "daily" | "specific_days";
  active_days: number[] | null;
  created_at: string;
  archived_at: string | null;
};
`;

export function generate() {
  const parts = SOURCES.map((rel) => {
    const src = readFileSync(path.join(root, rel), "utf8").replace(/\r\n/g, "\n");
    const body = src
      .split("\n")
      .filter((line) => !/^import\s.+from\s.+;\s*$/.test(line))
      .join("\n")
      .trim();
    return `// ---- ${rel} ----\n${body}\n`;
  });
  return `${HEADER}\n${parts.join("\n")}`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, generate());
  console.log(`wrote ${path.relative(root, OUT)}`);
}
